// Selected official TeamTopContent; generated by prepare_activity_battle_rank_ui.py.
using Zjcs.Official.WorldUI;
using Zjcs.Official.ProfessionUI;
using Zjcs.Official.TeamUI;
namespace Zjcs.Official.ActivityRankUI
{
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class TeamTopContent : MonoBehaviour, LoopScrollDataSource
{
	[SerializeField]
	private TopRankTeamItem mMeTopItem;

	[SerializeField]
	private LoopVerticalScrollRect mScrollRect;

	[SerializeField]
	private WorldMultiLanguageText mFirstRankTipText;

	[SerializeField]
	private List<WorldMultiLanguageText> mFirstScoreText;

	[SerializeField]
	private WorldMultiLanguageText mNotInRankTipText;

	[SerializeField]
	private CanvasGroup mContent;

	[SerializeField]
	private List<TeamTopContentFirstItem> mFirstItems;

	[SerializeField]
	private WorldStateSwitcher<bool> mEmptyStateSwitcher;

	[SerializeField]
	private WorldStateSwitcher<bool> mMyTopStateSwitcher;

	private TeamTopContentDataBase mTopContentData;
	private ActivityRankBindings bindings;
	public void Configure(ActivityRankBindings value)
	{ bindings = value; mMeTopItem.Configure(value); foreach (var item in mFirstItems) item.Configure(value); }

	public ActivityDomainBossRankKey CurrentTopKey { get; protected set; }

	public void Init(ActivityDomainBossRankKey topKey, TeamTopContentDataBase topContentData)
	{
		CurrentTopKey = topKey;
		mTopContentData = topContentData;
		RefreshContent();
	}

	public void RefreshContent(Action completeCallback = null)
	{
		mFirstRankTipText.SetKey(mTopContentData.GetFirstRankTipKey());
		mNotInRankTipText.SetKey(mTopContentData.GetNotInRankTipKey());
		SetAlphaAndInteractable(0f);
		mTopContentData.InitData(CurrentTopKey, () =>
		{
			InitFinishCallBack();
			completeCallback?.Invoke();
		});
	}

	private void SetAlphaAndInteractable(float alpha)
	{ mContent.alpha = alpha; mContent.interactable = alpha > 0; mContent.blocksRaycasts = alpha > 0; }

	private void InitFinishCallBack()
	{
		ShowContent();
		SetAlphaAndInteractable(1f);
	}

	private void ShowContent()
	{
		int showCount = mTopContentData.GetShowCount();
		mEmptyStateSwitcher.SetState(showCount <= 0);
		if (showCount <= 0)
		{
			foreach (WorldMultiLanguageText item in mFirstScoreText)
			{
				item.SetKey(mTopContentData.GetEmptyResultTipKey());
			}
		}
		else
		{
			ShowFirst();
		}
		ShowMySelf();
		mScrollRect.dataSource = this;
		mScrollRect.totalCount = Mathf.Clamp(showCount - 1, 0, bindings.ShowPlayerCountLimit);
		mScrollRect.RefillCells();
	}

	private void ShowFirst()
	{
		TeamTopContentData dataByIndex = mTopContentData.GetDataByIndex(0);
		IEnumerator<WorldMultiLanguageText> enumerator = mFirstScoreText.GetEnumerator();
		foreach (object score in TopRankTeamItem.GetScores(dataByIndex.Score))
		{
			if (!enumerator.MoveNext())
			{
				break;
			}
			enumerator.Current.SetKey(score.ToString());
		}
		int i = 0;
		foreach (long playerId in dataByIndex.PlayerIds)
		{
			IProfessionInfoTarget targetData = bindings.PlayerTarget(playerId);
			mFirstItems[i].Init(targetData);
			i++;
		}
		foreach (ActivityRankNpcTarget npcTargetData in dataByIndex.NpcTargetDatas)
		{
			mFirstItems[i].Init(npcTargetData);
			i++;
		}
		for (; i < mFirstItems.Count; i++)
		{
			mFirstItems[i].Init(null);
		}
	}

	private void ShowMySelf()
	{
		TeamTopContentData mySelfData = mTopContentData.GetMySelfData();
		if (mySelfData.Rank < 0)
		{
			mMyTopStateSwitcher.SetState(state: false);
			return;
		}
		mMeTopItem.Init(mySelfData);
		mMyTopStateSwitcher.SetState(state: true);
	}

	public void ProvideData(Transform transform, int idx)
	{
		TopRankTeamItem component = ((Component)transform).GetComponent<TopRankTeamItem>();
		component.Configure(bindings);
		TeamTopContentData dataByIndex = mTopContentData.GetDataByIndex(idx + 1);
		component.Init(dataByIndex);
	}
}
}
